#!/usr/bin/env bash
# ABOUTME: Safe smoke script for the LunaRoute Djev endpoint used by djev-sensors.
# ABOUTME: Reads the API key from the environment; never commit a literal key here.
set -eu
curl -fsS https://gw.lunaroute.com/v1/systemone -H "Authorization: Bearer ${LUNAROUTE_API_KEY:?set LUNAROUTE_API_KEY}" -H 'Content-Type: application/json' -d '{"model":"djev","state":"Support ticket #48213 from a Pro-plan customer, opened 6 hours ago.\nSubject: '\''Charged twice and now the dashboard is blank.'\''\nBody: '\''Your checkout charged my card twice for the same annual upgrade on Tuesday. I opened billing to check, and now the entire dashboard shows a blank white page. I have a demo for my own customers in 40 minutes and I cannot log in or export anything. I already lost one customer this week because of this. Please fix it now.'\''\nAccount: acme-corp (org 9912), MRR $1,450, 3 seats, no prior escalations.\nBilling ledger: two successful charges of $1,450 on Tuesday, 3 seconds apart, same invoice id INV-77821.\nStatus page: no open incidents on the dashboard service.\nInternal note from support: '\''card processor did not return an idempotency key on retry.'\''","questions":{"urgent":{"type":"noul","instructions":"Does this ticket need immediate attention (within the next 15 minutes)?"},"team":{"type":"choice","instructions":"Which team should own this ticket?","criteria":{"billing":"Duplicate charges, invoices, refunds, payment methods","engineering":"Broken features, outages, blank pages, login failures","customer_success":"Onboarding, plan questions, demos, general account help","trust_and_safety":"Abuse, fraud, account takeover"}},"next_action":{"type":"choice","instructions":"What should the first responder do?","criteria":{"refund_duplicate":"Refund the duplicate charge and confirm in writing","page_oncall":"Page the on-call engineer for the dashboard outage","reply_only":"Send a written reply and wait for the customer","escalate_account":"Escalate to the account owner before replying"}},"churn_risk":{"type":"score","instructions":"How likely is this customer to churn if we do not resolve it today?","criteria":["low","medium","high"]}}}' | python3 -m json.tool
